create table if not exists public.cargo_unit_labels(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,cargo_unit_id uuid not null references public.cargo_units(id) on delete cascade,sequence_no integer not null check(sequence_no>0),sequence_total integer not null check(sequence_total>0),tracking_code text not null,created_at timestamptz not null default now(),unique(cargo_unit_id,sequence_no),unique(organization_id,tracking_code));
alter table public.cargo_unit_labels enable row level security;
drop policy if exists cargo_unit_labels_org on public.cargo_unit_labels;
create policy cargo_unit_labels_org on public.cargo_unit_labels for all using(organization_id in(select organization_id from public.organization_members where user_id=auth.uid())) with check(organization_id in(select organization_id from public.organization_members where user_id=auth.uid()));
create or replace function public.ensure_cargo_unit_labels(p_cargo_unit_id uuid) returns integer language plpgsql security invoker set search_path=public as $$
declare c cargo_units%rowtype;total integer;i integer;prefix text;
begin select * into c from cargo_units where id=p_cargo_unit_id for update;if not found then raise exception 'Cargo not found';end if;if c.quantity is null or c.quantity<=0 or c.quantity<>trunc(c.quantity) then raise exception 'Individual labels require a positive whole-number quantity';end if;total:=c.quantity::integer;prefix:=coalesce(nullif(c.uin,''),nullif(c.handling_unit_code,''),'CU-'||upper(substr(replace(c.id::text,'-',''),1,10)));for i in 1..total loop insert into cargo_unit_labels(organization_id,cargo_unit_id,sequence_no,sequence_total,tracking_code) values(c.organization_id,c.id,i,total,prefix||'-'||lpad(i::text,greatest(3,length(total::text)),'0')) on conflict(cargo_unit_id,sequence_no) do update set sequence_total=excluded.sequence_total;end loop;delete from cargo_unit_labels where cargo_unit_id=c.id and sequence_no>total;update cargo_units set track_individually=true,label_profile=coalesce(label_profile,'INDIVIDUAL') where id=c.id;return total;end $$;
grant execute on function public.ensure_cargo_unit_labels(uuid) to authenticated;